<?php require '../config/auth.php';login_required('company');$page_title='Post Job';$q=$pdo->prepare('SELECT * FROM companies WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$c=$q->fetch();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($c['approval_status']!=='approved')$err='Your company must be approved by admin before posting jobs.';else{$s=$pdo->prepare("INSERT INTO jobs(company_id,job_title,description,responsibilities,required_skills,qualification,department,min_cgpa,passing_year,package_lpa,location,job_type,openings,application_deadline,selection_process,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending')");$s->execute([$c['id'],$_POST['job_title'],$_POST['description'],$_POST['responsibilities'],$_POST['required_skills'],$_POST['qualification'],$_POST['department'],$_POST['min_cgpa'],$_POST['passing_year'],$_POST['package_lpa'],$_POST['location'],$_POST['job_type'],$_POST['openings'],$_POST['deadline'],$_POST['selection_process']]);flash('Job submitted for admin approval.');go('manage-jobs.php');}}require '../config/header.php';?><div class="head"><div><h1>Post a Job</h1><p>Create a structured campus opportunity.</p></div></div><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="card"><div class="row"><div class="fg"><label>Job Title *</label><input class="control" name="job_title" required></div><div class="fg"><label>Department</label><input class="control" name="department"></div></div><div class="row"><div class="fg"><label>Qualification</label><input class="control" name="qualification"></div><div class="fg"><label>Minimum CGPA</label><input class="control" name="min_cgpa" type="number" step=".01" min="0" max="10" value="6"></div></div><div class="row"><div class="fg"><label>Passing Year</label><input class="control" name="passing_year" value="<?=date('Y')?>"></div><div class="fg"><label>Package (LPA)</label><input class="control" name="package_lpa" type="number" step=".1"></div></div><div class="row"><div class="fg"><label>Location</label><input class="control" name="location"></div><div class="fg"><label>Job Type</label><select class="control" name="job_type"><option>Full-time</option><option>Internship</option><option>Hybrid</option><option>Remote</option></select></div></div><div class="row"><div class="fg"><label>Openings</label><input class="control" name="openings" type="number" min="1" value="1"></div><div class="fg"><label>Application Deadline</label><input class="control" name="deadline" type="date" required></div></div><div class="fg"><label>Required Skills</label><input class="control" name="required_skills" placeholder="PHP, MySQL, JavaScript"></div><div class="fg"><label>Job Description</label><textarea class="control" name="description" rows="4"></textarea></div><div class="fg"><label>Responsibilities</label><textarea class="control" name="responsibilities" rows="4"></textarea></div><div class="fg"><label>Selection Process</label><textarea class="control" name="selection_process" placeholder="Aptitude → Technical → HR"></textarea></div><button class="btn primary">Submit for Approval</button></div></form><?php require '../config/footer.php';?>
